test('respects backoffLimit', withServer, async (t, server, got) => {
	let count = 0;
	const computedDelays: number[] = [];
	server.get('/', (_request, response) => {
		count++;
		if (count === 3) {
			response.end('ok');
		} else {
			response.statusCode = 408;
			response.end();
		}
	});

	const body = await got('', {
		retry: {
			backoffLimit: 0,
			calculateDelay({computedValue}) {
				computedDelays.push(computedValue);
				t.true(computedValue >= 0 && computedValue <= 100);
				return computedValue;
			},
		},
	}).text();

	t.is(body, 'ok');
	t.is(count, 3);
	t.is(computedDelays.length, 2);
});

